data.es = data.en.map(item => ({
    ...item,
    title: item.title
        .replace(/^Programming:/, "Programación:")
        .replace(/^Computer Science:/, "Informática:")
        .replace(/^Science:/, "Ciencia:")
        .replace(/^Mathematics:/, "Matemáticas:")
        .replace(/^Astronomy:/, "Astronomía:")
        .replace(/^Geography:/, "Geografía:")
        .replace(/^Technology:/, "Tecnología:")
        .replace(/^Gaming:/, "Videojuegos:")
        .replace(/^Artificial Intelligence:/, "Inteligencia artificial:")
        .replace(/^Engineering:/, "Ingeniería:")
        .replace(/^History:/, "Historia:")
        .replace(/^Languages:/, "Idiomas:")
        .replace(/^Arts:/, "Arte:")
        .replace(/^Transport:/, "Transporte:")
        .replace(/^Energy:/, "Energía:")
        .replace(/^Nature:/, "Naturaleza:")
        .replace(/^Food:/, "Alimentación:")
        .replace(/^Business:/, "Negocios:")
        .replace(/^Internet:/, "Internet:"),
    desc: "Base de datos NeoFind: " + item.title + ". Información, definiciones, usos y temas relacionados."
}));

